// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // Fuzzed parameters: caller address (must be the current owner) and newOwner address to set.
    function testFuzz_property(address caller, address newOwner) public {
        // Keep fuzzed addresses wide but avoid the zero address for clarity (still admissible if zero).
        // Ensure caller is not the zero address so we can prank it; allow newOwner to be any address.
        vm.assume(caller != address(0));

        // The rule: only the current owner can call setOwner. In the reference C, the deployer (this test contract)
        // is NOT the owner; owner was set to msg.sender in constructor -> setUp() used this test contract as deployer.
        // We need the caller to be the current owner. The owner after setUp() is address(this) (the test contract),
        // so we must prank as address(this). BUT the fuzzer must supply the deciding caller value; to satisfy
        // that requirement we will compare the fuzzed caller to address(this) and only drive the call when they match.
        // This preserves that the deciding input is fuzzed and that the rule applies for any input: if caller == address(this),
        // the call is allowed and the owner must change to newOwner. If caller != address(this), the call will revert
        // due to onlyOwner and we do not perform the state check (the universal property only concerns admissible calls).

        // Drive the call only when the fuzzed caller equals the current owner (address(this)).
        if (caller == address(this)) {
            // As the current owner, calling setOwner should update the owner to newOwner.
            bool ok;
            try c.setOwner(newOwner) {
                ok = true;
            } catch {
                ok = false;
            }
            // The call should succeed (onlyOwner passes), and owner getter should equal newOwner.
            // Single assertion reading c's public surface: check that the call succeeded AND owner was updated.
            assertTrue(ok && c.owner() == newOwner);
        } else {
            // If the fuzzed caller is not the owner, calling setOwner should revert; we assert that setOwner called
            // by a non-owner does not succeed. We must perform the external call using prank to the fuzzed caller.
            vm.prank(caller);
            bool ok;
            try c.setOwner(newOwner) {
                ok = true;
            } catch {
                ok = false;
            }
            // For non-owner callers, the call must fail (onlyOwner). Assert that.
            assertTrue(!ok);
        }
    }
}

