pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // Fuzz parameter: any address candidate for new owner
    function testFuzz_property(address newOwner) public {
        // Keep domain wide; exclude zero address only if desired — here allow zero as admissible too
        // The property: after calling setOwner(newOwner) from the current owner, c.owner() == newOwner
        // Arrange: call as the current owner (deployer from setUp is this test contract by default)
        // by default c was created by this contract (setUp), so address(this) is owner
        // Act: call setOwner with fuzzed newOwner
        bool ok;
        try c.setOwner(newOwner) {
            ok = true;
        } catch {
            // If call reverts, treat as failing to set; ok=false
            ok = false;
        }

        // If the call succeeded, the reference implementation guarantees owner() == newOwner for all inputs.
        // The mutant may store a different address for some inputs; so assert that whenever setOwner returned
        // success, the public getter owner() equals the supplied newOwner.
        // Single assertion reading c's public getter.
        if (ok) {
            assertTrue(c.owner() == newOwner);
        } else {
            // If call reverted, the reference would only revert if caller wasn't owner; in our setup the caller is owner
            // so reference never reverts; but to keep the single assertTrue requirement, assert that a revert did not occur.
            // However, we still must have exactly one assertTrue in the function — so we combine into one final check:
            // The reference never reverts here, so require ok == true.
            assertTrue(ok);
        }
    }
}

