pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // General rule: for any address newOwner, when the current owner calls setOwner(newOwner),
    // the contract's public owner getter equals newOwner afterwards.
    // The mutant that assigns owner = payable(_owner) can cause owner != newOwner for some addresses;
    // fuzzing newOwner should find such a case.
    function testFuzz_property(address newOwner) public {
        // keep domain wide; no vm.assume or bound to not exclude interesting addresses

        // ensure the current msg.sender is the owner (deployer from setUp)
        // call setOwner as the owner
        vm.prank(address(this)); // address(this) is not the deployer; ensure we call from the deployer
        // But in setUp we deployed c with this contract as msg.sender, so address(this) is the owner.

        // perform the ownership transfer
        try c.setOwner(newOwner) {
            // success
        } catch {
            // If it reverts, the invariant about storage equality is not observable; we treat revert as failure
            // but the reference implementation should not revert here. Marking as false will fail the test on ref
        }

        // Exactly one assertion: after the call, owner getter equals the argument passed.
        // This holds for the correct contract for all addresses, but the mutant may store a different value.
        assertTrue(c.owner() == newOwner);
    }
}

