pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    // Fuzz parameter: an arbitrary address candidate for new owner
    function testFuzz_property(address newOwner) public {
        // Keep domain wide: disallow zero address only if needed; here we allow all addresses
        // Record contract balance before the call
        uint256 balBefore = address(c).balance;

        // Ensure the current owner (deployer) is the msg.sender for setOwner call
        // c was deployed in setUp() by this test contract's tx origin; we must call as that deployer
        // The test contract is already the deployer in setUp, so just call directly

        bool ok;
        try c.setOwner(newOwner) returns (bool) {
            ok = true;
        } catch {
            ok = false;
        }

        // Exactly one assertion: the correct contract never moves Ether during setOwner calls,
        // so address(c).balance must remain equal to balBefore for all inputs; the mutant that
        // performs an unintended transfer when converting to payable would cause the balance to change
        uint256 balAfter = address(c).balance;
        assertTrue(balAfter == balBefore);
    }
}

