pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // General rule: For any address newOwner, when the current owner calls setOwner(newOwner),
    // the public getter owner() equals newOwner after the call (the correct contract always stores the exact address passed).
    // The mutant that assigns owner = payable(_owner) can lead to a differing stored value for some inputs; the fuzzer will find such inputs.
    function testFuzz_property(address newOwner) public {
        // keep domain wide: disallow only the zero-address to avoid degenerate trivialities
        vm.assume(newOwner != address(0));

        // Current test deployer is the owner (setUp deployed c), so call as that owner
        address caller = address(this);
        vm.prank(caller);
        bool ok;
        try c.setOwner(newOwner) {
            ok = true;
        } catch {
            ok = false;
        }

        // The universal property we assert: if the call returned (ok == true), then the public owner getter equals the exact passed address
        // We express it as a single assertTrue that reads c.owner(). For failing calls, we still require owner unchanged or equal newOwner is not required;
        // but to keep a single assert, we assert that either the call reverted (ok == false) is false (i.e., call succeeded) implies owner==newOwner.
        // Implemented as: ok => owner==newOwner. To encode as one assertTrue, we assert that (!ok) || (c.owner() == newOwner)
        assertTrue((!ok) || (c.owner() == newOwner));
    }
}

