pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // Fuzzed params: newOwner (address) and funds (uint256) to ensure we cover cases where an unexpected transfer
    // in a mutant would change address(c).balance. We keep funds wide but bounded to avoid overflow in vm.deal.
    function testFuzz_property(address newOwner, uint256 funds) public {
        // keep funds in a practical range so vm.deal doesn't revert (but still wide)
        funds = bound(funds, 0, 1 ether);

        // ensure the caller is the current owner (deployed C() set owner to address(this) by constructor)
        // fund msg.sender so any mutant that attempts to send value from caller is possible
        vm.deal(address(this), 1 ether);

        // record balance before the call
        uint256 balBefore = address(c).balance;

        // perform call as the current owner (this contract)
        bool ok;
        try c.setOwner(newOwner) {
            ok = true;
        } catch {
            ok = false;
        }

        // The general rule we assert: for ANY input, the correct contract never moves funds during setOwner
        // and stores exactly the provided address as owner if the call succeeded. We observe both via
        // address(c).balance and the public owner getter. This single assertTrue encodes that
        // (1) call did not change contract balance, and (2) if call returned normally then owner==newOwner.
        // The buggy mutant that introduces payable-related/value semantics can either change balance or store a
        // different owner for some inputs; the fuzzing will find such inputs.
        address stored = c.owner();
        // single assertion required: combine both conditions into one boolean
        assertTrue(address(c).balance == balBefore && (!ok || stored == newOwner));
    }
}

